-- ------------------------------------------------------------------ registrants
-- Vibe Coding (Apr 2569, still the 2568 academic year): today's year 2+ were a
-- year lower; about half came; 1015 didn't.
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 106000 + ROW_NUMBER() OVER (ORDER BY u.id), 1060, u.id,
       CONCAT('นักศึกษาชั้นปีที่ ', CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) - 1, SUBSTRING(u.dept, LOCATE(' · ', u.dept))),
       IF(u.id = 1015, 'absent', 'attended'), IF(u.id = 1015, 0, 1),
       IF(u.id = 1015, NULL, TIMESTAMP('2026-04-10', '16:30:00')), 'onsite',
       TIMESTAMP('2026-03-16' + INTERVAL (u.id % 19) DAY, '20:40:00')
FROM users u
WHERE u.role = 'student' AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 2 AND u.id % 2 = 1;

-- Upskill/Reskill (Jul 2569): some onsite, some online; 1006 didn't come.
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 106100 + ROW_NUMBER() OVER (ORDER BY u.id), 1061, u.id, u.dept,
       IF(u.id = 1006, 'absent', 'attended'), IF(u.id = 1006, 0, 1),
       IF(u.id = 1006, NULL, TIMESTAMP('2026-07-05', '16:00:00')),
       IF(u.id % 3 = 0, 'online', 'onsite'),
       TIMESTAMP('2026-06-15' + INTERVAL (u.id % 16) DAY, '19:05:00')
FROM users u
WHERE u.role = 'student' AND u.id % 4 IN (2, 3);

-- Future Learning Explorer (Aug 2569): the student committee, every year.
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 106200 + ROW_NUMBER() OVER (ORDER BY u.id), 1062, u.id, u.dept,
       'attended', 1, TIMESTAMP('2026-08-02', SEC_TO_TIME(6 * 3600 + 40 * 60 + (u.id % 15) * 60)), 'onsite',
       TIMESTAMP('2026-07-20' + INTERVAL (u.id % 9) DAY, '17:30:00')
FROM users u
WHERE u.role = 'student' AND u.id % 2 = 0;

-- ------------------------------------------------------------------ check-ins, every day of each event
INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, d.day, TIMESTAMP(d.day, SEC_TO_TIME(d.open_s + (r.id % 24) * 60))
FROM registrations r
JOIN (SELECT 1060 AS event_id, DATE '2026-04-09' AS day, 8 * 3600 + 5 * 60 AS open_s
      UNION ALL SELECT 1060, DATE '2026-04-10', 8 * 3600 + 5 * 60
      UNION ALL SELECT 1061, DATE '2026-07-04', 8 * 3600 + 35 * 60
      UNION ALL SELECT 1061, DATE '2026-07-05', 8 * 3600 + 35 * 60
      UNION ALL SELECT 1062, DATE '2026-08-02', 6 * 3600 + 40 * 60) d ON d.event_id = r.event_id
WHERE r.checked_in = 1;

